// Reference dataset types — the single source of truth shared by the website
// reference pages (web) and the kapi-desktop Storybook fixtures.
//
// The dataset documents (formats.json / tools.json / commands.json) are
// generated by scripts/gen-refs (Go). The schema/doc types an entry carries are
// re-exported from the shared @neokapi/contract-types package (issue #817), so a
// dataset entry's `schema` is assignable to SchemaForm's `schema` prop and
// `doc.parameters` to `paramDocs` without a hand-maintained mirror.

// ── Schema-form types (re-exported from @neokapi/contract-types) ──
export type {
  ComponentSchema,
  FormatMeta,
  ToolMeta,
  ParameterGroup,
  ConditionExpr,
  LayoutHints,
  PropertySchema,
  ToolDocParam,
} from "@neokapi/contract-types";

import type { ComponentSchema, ToolDocParam } from "@neokapi/contract-types";

// ── Reference dataset types ─────────────────────────────────────────────────

/** Which engine provides an entry. */
export type ReferenceSource = "built-in" | "okapi" | "plugin";

/** Whether an entry is a data format or a processing tool. */
export type ReferenceKind = "format" | "tool";

/** A worked configuration example. */
export interface ReferenceExample {
  title: string;
  /** Markdown — see markdown-in-ui.md. */
  description?: string;
  /** Fenced YAML configuration snippet. */
  config?: string;
  input?: string;
  output?: string;
}

/** Rich reference documentation for an entry. `parameters` is handed to
 *  SchemaForm as its `paramDocs` prop unchanged.
 *  `overview`, `limitations`, and `processingNotes` are markdown — see
 *  markdown-in-ui.md. */
export interface ReferenceDoc {
  /** Markdown. */
  overview?: string;
  parameters?: Record<string, ToolDocParam>;
  /** Markdown items. */
  limitations?: string[];
  /** Markdown items. */
  processingNotes?: string[];
  examples?: ReferenceExample[];
  wikiUrl?: string;
}

/** One format or tool in the reference dataset. */
export interface ReferenceEntry {
  id: string;
  source: ReferenceSource;
  kind: ReferenceKind;
  displayName: string;
  /** Markdown — see markdown-in-ui.md. */
  description?: string;

  // Format-only metadata.
  extensions?: string[];
  mimeTypes?: string[];
  hasReader?: boolean;
  hasWriter?: boolean;

  // Tool-only metadata.
  category?: string;
  inputs?: string[];
  outputs?: string[];
  tags?: string[];
  requires?: string[];
  cardinality?: string;
  /** IO contract ports as "type@side" tokens (consumed ports add a trailing "?" when optional). */
  consumes?: string[];
  produces?: string[];
  /** External systems the tool reads/writes (e.g. "tm-read", "api-call"). */
  sideEffects?: string[];
  /** Whether the tool is a transformer — it may rewrite the source (CapTransform). */
  isSourceTransform?: boolean;
  /** A recoverable transformer (redaction) vaults originals and restores them later. */
  recoverable?: boolean;
  aliases?: string[];

  /** The schema consumed verbatim by the shared SchemaForm renderer. */
  schema?: ComponentSchema;
  doc?: ReferenceDoc;
  presets?: Record<string, Record<string, unknown>>;
}

/** Top-level document for formats.json / tools.json. */
export interface ReferenceDataset {
  generatedAt: string;
  kind: ReferenceKind;
  entries: ReferenceEntry[];
}

/** One missing-metadata finding. */
export interface ReferenceGap {
  kind: ReferenceKind;
  source: ReferenceSource;
  id: string;
  field: string;
  detail: string;
}

/** Top-level document for reference-gaps.json. */
export interface ReferenceGapReport {
  generatedAt: string;
  summary: Record<string, number>;
  gaps: ReferenceGap[];
}

// ── Command reference types ─────────────────────────────────────────────────

/** One flag on a CLI command. */
export interface CommandFlag {
  /** Long flag name (without --). */
  name: string;
  /** Single-character shorthand (without -). Absent when not set. */
  shorthand?: string;
  /** Human-readable usage description. */
  usage?: string;
  /** Default value as a string (empty string when the default is ""). */
  default?: string;
  /** Go pflag value type, e.g. "string", "bool", "int", "stringSlice". */
  type?: string;
}

/** One command or subcommand in the kapi CLI. */
export interface CommandEntry {
  /**
   * Dot-joined command path, e.g. "formats.info".
   * Top-level commands have a single segment, e.g. "pseudo-translate".
   */
  id: string;
  /**
   * Ordered list of command name segments (root "kapi" is excluded),
   * e.g. ["formats", "info"].
   */
  path: string[];
  /** Cobra Use string, e.g. "info <format>". */
  use: string;
  /** One-line description. */
  short?: string;
  /** Markdown. Multi-line description — see markdown-in-ui.md. */
  long?: string;
  /** Alternative command names. */
  aliases?: string[];
  /** Cobra command group ID, e.g. "processing", "management". */
  groupID?: string;
  /** Local flags registered on this command (excludes inherited persistent flags). */
  flags?: CommandFlag[];
  /** Non-empty lines from the cobra Example string. */
  examples?: string[];
  /**
   * True when this command can run inside the browser WASM build.
   * Derived from the kapi-wasm-cli buildRoot allowlist plus a curated
   * override map for commands that require network, the OS keychain,
   * SQLite (cgo), or a running server.
   */
  offlineCapable: boolean;
  /**
   * True when the command is present in the kapi-wasm-cli buildRoot and can
   * actually run in the browser playground — offline commands directly, AI/MT
   * commands via the demo provider. Gates the ▸ Run affordance.
   */
  runnableInBrowser: boolean;
  /**
   * True for commands that run in-browser only via the deterministic demo
   * provider (AI/MT). Their output is illustrative, not from a real model — the
   * UI labels these "Demo".
   */
  demoMode: boolean;
}

/** Top-level document for commands.json. */
export interface CommandDataset {
  generatedAt: string;
  commands: CommandEntry[];
}

/**
 * One addressable piece of a prompt, and who owns it. The framework owns `task`
 * and `constraint` (the rules that keep output usable); your project owns
 * `instruction`, `voice` and `glossary` (the steering); your document owns
 * `content` (data, never instruction).
 */
export interface PromptSection {
  kind: "task" | "constraint" | "instruction" | "voice" | "glossary" | "content";
  origin: string;
  heading?: string;
  text: string;
}

/** One message of a rendered prompt. */
export interface PromptTurn {
  role: "system" | "user";
  sections: PromptSection[];
}

/** One prompt kapi sends to a language model. */
export interface PromptEntry {
  id: string;
  /** The tool or command that sends it. */
  tool: string;
  summary: string;
  turns?: PromptTurn[];
  /**
   * A non-text part sent with the turns — a cropped image, a speech clip. Named
   * rather than rendered: it is the user's data, not prompt text.
   */
  attachment?: string;
}

/** Top-level document for prompts.json. */
export interface PromptDataset {
  generatedAt: string;
  /** The prompt catalog revision (prompt.Version). */
  version: string;
  prompts: PromptEntry[];
}

/** Where a model sits in its neokapi lifecycle. A model the provider stops serving
 *  is removed from the catalog, not marked retired, so there is no "retired". */
export type ModelStatus = "active" | "superseded";

/** One catalogued model — a family kapi ships support for, with its ceilings and
 *  neokapi lifecycle. Generated from providers/ai/models.json. */
export interface ModelEntry {
  /** Canonical model id, also the match prefix (a dated id resolves to it). */
  id: string;
  provider: string;
  /** Human-readable provider name (e.g. "Anthropic"). */
  providerLabel: string;
  label: string;
  /** Bare names that resolve here (e.g. the claude-code aliases sonnet/opus/haiku). */
  aliases?: string[];
  /** Providers whose built-in default this model is. */
  defaultFor?: string[];
  /** Whether this is a sensible primary choice for kapi's tasks. False = a
   *  capable-but-premium or off-task model, shown under "Advanced" not hidden. */
  recommended: boolean;
  maxOutputTokens?: number;
  contextWindow?: number;
  status: ModelStatus;
  /** Date this model id entered neokapi's source tree (YYYY-MM-DD). */
  introduced?: string;
  /** The id of the model that replaced this one, when superseded. */
  supersededBy?: string;
  /** A scheduled future retirement the vendor has announced (YYYY-MM-DD) — a
   *  warning on a still-live model. Actually-retired models are removed. */
  retirementDate?: string;
  note?: string;
}

/** The generated model catalog for the /models reference page. */
export interface ModelDataset {
  generatedAt: string;
  /** Date the catalog was last reviewed. */
  asOf: string;
  note: string;
  models: ModelEntry[];
}

// ── MCP reference ───────────────────────────────────────────────────────────

/**
 * Which `kapi mcp` surface exposes a tool: the curated default an assistant
 * gets on connect, or the sets `--all-tools` / `--all-flows` add.
 */
export type MCPSurface = "default" | "all-tools" | "all-flows";

/** One top-level property of an MCP tool's input schema. */
export interface MCPParam {
  name: string;
  type: string;
  required: boolean;
  description?: string;
}

/** One tool as an MCP client sees it on `tools/list`. */
export interface MCPTool {
  name: string;
  description: string;
  surface: MCPSurface;
  params?: MCPParam[];
}

/**
 * The generated MCP reference: the tools a live `kapi mcp` server answers to,
 * collected over an in-memory transport so the published table is the
 * registration source rendered rather than a hand copy of it.
 */
export interface MCPDataset {
  generatedAt: string;
  tools: MCPTool[];
}
